"""Explain wait-event API forms and timeout result regions."""
import json
from rewrite_c_beginner import rewrite, ROOT
ROWS={'os1473': ('문이 열릴 때까지 기다리는 행동과, 결과 번호를 돌려주는 계산은 다릅니다. 어떤 대기 도구는 끝난 뒤 다음 줄로 진행할 뿐 숫자 답을 주지 않습니다.', '일반 wait_event의 문장 형태와 조건 충족 시 즉시 끝나는 경로를 배웁니다.', 'wait_event(queue, ready);를 쓰고 “결과 숫자를 대입하지 않음”이라고 적으세요. ready가 처음부터 참이면 내부 등록을 건너뛰는 화살표를 그리세요.', ['wait_event는 조건이 참이 될 때까지 기다리는 커널 매크로입니다. 매크로는 컴파일 전에 정해진 코드로 펼쳐지는 규칙입니다. 바깥 모양은 do { ... } while (0)으로 여러 문장을 하나의 문장처럼 사용할 수 있게 묶습니다.', '그래서 result = wait_event(...)처럼 정수 결과를 받아 쓰는 표현식이 아닙니다. wait_event(queue,condition);처럼 하나의 문장으로 씁니다. 앞의 rcuwait_wait_event가 성공값 0을 주는 것과 이름이 비슷해도 사용법이 다릅니다.', '먼저 might_sleep로 잠들 수 있는 문맥인지 점검합니다. 이것이 잠들 수 없는 문맥을 자동으로 바꾸어 주지는 않습니다. spinlock을 잡고 있거나 인터럽트 처리 중인 곳에서 마음대로 사용하는 대기 도구가 아닙니다.', '다음으로 조건을 검사합니다. 처음부터 참이면 break로 바깥 묶음을 끝내고 내부 대기 항목도 등록하지 않습니다. 이미 준비된 음식 앞에서 줄을 새로 서지 않는 것과 같습니다. might_sleep 점검은 이 조건 검사보다 앞에 있습니다.', '조건이 거짓이면 TASK_UNINTERRUPTIBLE 상태, 비 exclusive 등록, schedule 명령을 사용하는 공통 대기로 갑니다. 이 버전은 신호 중단용 오류 반환을 제공하지 않습니다. 깨운 뒤에도 실제 조건은 반복해서 확인합니다.', '호출하는 쪽은 조건을 바꾼 뒤 맞는 깨우기를 해야 합니다. 조건을 보았다는 사실만으로 공유 자원의 독점권을 얻는 것은 아니므로 자료 보호 규약도 지킵니다. 조건식은 등록 전후와 깨어난 뒤 여러 번 읽힐 수 있어 반복 평가를 고려해야 합니다.'], [('일반 wait_event를 int 결과를 받는 대입식으로 써야 할까요?', ['네. 모든 대기 매크로는 int 값을 줘요', '아니요. 바깥 형태는 do-while 문장이에요'], 'wait_event는 문장 형태이며 결과 숫자를 제공하는 표현식이 아닙니다. interruptible이나 timeout 변형의 반환 약속을 이 버전에 그대로 적용하면 안 됩니다.'), ('조건이 처음부터 참이어도 반드시 대기열에 등록할까요?', ['아니요. 내부 대기를 건너뛰고 끝낼 수 있어요', '네. 조건에 상관없이 prepare를 부릅니다'], '바깥 if(condition)의 break가 내부 __wait_event보다 앞에 있습니다. 따라서 조건 충족과 실제 등록·수면은 서로 다른 사건입니다.')]), 'os1474': ('음식을 기다리다가 준비됐으면 성공하고, 중단하라는 연락 때문에 나가면 별도의 표시를 받습니다. 단, 준비가 됐는지 먼저 확인하는 순서는 유지합니다.', '신호로 중단 가능한 대기의 0과 -ERESTARTSYS를 구별합니다.', '처음 조건 참 → 0, 기다린 뒤 조건 참 → 0, 조건 거짓·허용 신호 → -ERESTARTSYS를 적으세요. 시간 제한 인자는 없다고 표시하세요.', ['wait_event_interruptible은 TASK_INTERRUPTIBLE 상태로 기다리는 변형입니다. interruptible은 여기서 신호에 의해 기다림을 중단할 수 있다는 뜻입니다. 하드웨어 인터럽트 처리 중에 이 함수를 사용해도 된다는 뜻은 아닙니다.', '바깥 매크로는 int __ret를 0으로 준비합니다. condition이 이미 참이면 내부 대기를 건너뛰고 0을 반환합니다. 조건이 거짓일 때 내부 반복으로 들어갑니다. 이 버전은 일반 wait_event와 달리 반환값을 받아 확인할 수 있습니다.', '내부 반복은 준비 함수의 결과를 받은 다음에도 조건을 먼저 검사합니다. 조건이 참이면 성공값 0으로 끝납니다. 조건이 거짓이고 중단 가능한 신호가 있으면 -ERESTARTSYS를 반환합니다.', '예를 들어 깨우기와 신호가 가까운 시점에 들어와도 조건을 참으로 관측했다면 조건 성공 길을 먼저 고를 수 있습니다. “신호가 조금이라도 있으면 무조건 실패”라는 식으로 외우면 원문의 검사 순서를 놓칩니다.', '-ERESTARTSYS는 커널의 시스템 호출 재시작 처리와 연결되는 내부 오류입니다. 사용자 화면에 언제나 이 번호가 그대로 나오거나 호출이 무조건 자동 재시작된다고 단정하지 않습니다. 상위 호출의 약속에 따라 처리해야 합니다.', '이 함수에는 timeout 인자가 없으므로 남은 시간을 양수로 돌려주는 규칙이 없습니다. 0은 성공, 음수 오류는 중단으로 확인하세요. 조건 변경 뒤의 깨우기, 공유 자료 보호, 반복 평가해도 안전한 조건식은 여전히 필요합니다.'], [('wait_event_interruptible에서 조건이 맞아 끝나면 반환값은?', ['항상 남은 시간이라는 양수예요', '0이에요'], '초기 결과 0을 조건 성공에서 유지합니다. 이 함수는 시간 제한 인자를 받지 않으므로 남은 timeout을 반환한다는 답은 맞지 않습니다.'), ('이 API가 신호 때문에 중단될 때의 코드는?', ['-ERESTARTSYS예요', '언제나 -ETIME이에요'], '공통 준비 함수가 -ERESTARTSYS를 알리고 매크로가 전달합니다. -ETIME은 다른 고해상도 시간 만료 계약에 등장하는 값이므로 신호 중단 코드와 섞으면 안 됩니다.')]), 'os1475': ('기다릴 시간 칸을 다 쓴 순간 음식이 준비됐을 수도 있습니다. “준비 안 됨·시간 끝”과 “마지막 확인에서 준비됨”을 서로 다른 값으로 알려 줍니다.', 'jiffies 단위의 남은 시간과 만료 경계 성공을 배웁니다.', '남은 시간 3·조건 참 → 3, 남은 시간 0·조건 거짓 → 0, 남은 시간 0·조건 참 → 1을 적으세요. 마지막 1은 정확한 잔여 시간과 다를 수 있습니다.', ['wait_event_timeout은 조건을 기다리되 시간 한도를 둡니다. timeout의 단위는 jiffies입니다. jiffy는 커널 시간 단위이고 길이는 설정에 따라 달라지므로 숫자 100을 무조건 100밀리초라고 읽으면 안 됩니다.', 'long __ret에 시간 값을 저장하고 ___wait_cond_timeout으로 조건과 만료를 함께 검사합니다. 조건이 이미 참이거나 시간이 0이라면 바깥 검사에서 내부 대기를 생략할 수도 있습니다. might_sleep 점검은 그보다 먼저 합니다.', '실제로 기다릴 때는 schedule_timeout의 반환값을 __ret에 다시 저장합니다. 받은 값은 남은 시간입니다. 처음 5에서 대기 후 3이 됐다면 다음에는 3을 써서 기다리므로 매번 처음 5로 되돌리는 방식이 아닙니다.', '조건이 거짓인 채 시간이 끝나면 0입니다. 시간이 남아 있을 때 조건이 참이면 남은 jiffies를 양수로 반환합니다. 예를 들어 남은 값이 3이면 결과도 3입니다. 이 양수는 조건 성공으로 해석합니다.', '시간이 0이 된 경계에서 조건이 참이면 도우미가 결과를 1로 조정합니다. 만료 실패의 0과 구별하기 위해서입니다. 따라서 결과 1은 진짜 한 jiffy가 남은 성공일 수도 있고, 남은 시간 0에서 조건을 확인한 성공일 수도 있습니다.', '반환 1만 보고 정확히 언제 깨어났는지 계산하면 안 됩니다. 또한 시간 한도가 있다고 조건 변경 후 wake 규약을 생략해도 되는 것은 아닙니다. 적절한 깨우기가 있어야 준비된 상황을 기다리는 쪽이 제때 다시 확인할 수 있습니다.'], [('남은 시간이 0인 경계에서 조건이 참이면 반환값은?', ['언제나 만료를 뜻하는 0이에요', '성공을 구별하는 1이에요'], '도우미는 조건이 참이고 결과가 0이면 1로 바꿉니다. 마지막 확인에서 성공했는지 구별하므로 경계라고 무조건 실패는 아닙니다.'), ('wait_event_timeout의 시간 인자 단위는?', ['jiffies예요', '항상 마이크로초예요'], '원문이 timeout, in jiffies라고 명시합니다. 실제 시간으로 바꿀 때는 커널 설정과 변환 규약을 사용해야 하므로 숫자만 보고 마이크로초로 읽으면 안 됩니다.')]), 'os1476': ('결과 표지판에 양수·0·음수 세 종류가 있다고 합시다. 0이 아닌지만 보면 양수 성공과 음수 오류를 구별할 수 없습니다.', '신호 중단 가능한 시간 제한 대기의 세 반환 영역을 나누어 처리합니다.', 'ret=3 → 성공, ret=0 → 만료, ret=-ERESTARTSYS → 신호 중단을 쓰세요. if(ret)는 첫째와 셋째 모두 참이라고 표시하세요.', ['wait_event_interruptible_timeout은 조건 성공, 시간 만료, 신호 중단을 함께 다룹니다. TASK_INTERRUPTIBLE로 기다리고 시간 도우미와 schedule_timeout을 사용합니다. 비슷한 이름의 다른 대기 함수와 반환 계약을 비교해야 합니다.', '조건 성공이면 양수입니다. 보통 남은 jiffies이며, 남은 시간이 0인 경계에서 조건이 참이면 성공 표시 1로 바뀝니다. 조건이 거짓인 채 시간이 다 되면 0입니다. 시간이 남고 조건도 거짓일 때 허용 신호로 중단하면 -ERESTARTSYS입니다.', '검사 순서는 조건·만료 도우미가 신호 분기보다 앞입니다. 따라서 동시에 관측해도 조건 참이면 성공이 먼저이고, 조건 거짓·시간 0이면 만료가 먼저입니다. 단순히 신호가 있으면 어떤 상태에서든 오류가 우선이라고 읽지 마세요.', 'C의 if(ret)는 0이면 거짓, 0이 아니면 참입니다. 음수도 0이 아니므로 참입니다. 그래서 if(ret)를 성공 조건으로 쓰면 -ERESTARTSYS까지 성공으로 처리할 수 있습니다. C의 참·거짓 규칙과 API의 성공 약속은 다른 것입니다.', '결과는 ret>0, ret==0, ret<0으로 나누어 읽습니다. >는 크다, ==는 같다, <는 작다입니다. 각각 조건 성공, 조건 미충족 만료, 신호 오류에 대응합니다. 반환값을 받을 변수도 잔여 시간과 음수 오류를 담는 형식이어야 합니다.', '지역 결과 변수가 long인 이유는 잔여 timeout 값을 반환하기 때문입니다. 태스크 주소를 담는 포인터 변수가 아닙니다. 일반 interruptible의 int 성공·오류 코드와 달리 시간 값도 보존해야 합니다. long의 실제 비트 폭을 모든 환경에서 같다고 가정하지 않습니다.'], [('if(ret)만으로 이 함수의 성공 여부를 구별할 수 있을까요?', ['네. 0이 아니면 전부 성공이에요', '아니요. 음수 오류도 C에서는 참이에요'], '성공은 양수이고 오류는 음수입니다. 둘 다 0이 아니라 if(ret)에 들어가므로 >0, ==0, <0을 나눠 처리해야 합니다.'), ('반환 지역 변수를 long으로 두는 이유는?', ['남은 timeout 값을 담아 반환하기 위해서예요', '항상 task 포인터를 저장하려고요'], '이 매크로는 시간 값을 __ret에 보관하고 반환합니다. 주소가 아니라 정수 시간과 오류를 담는 자리이며, 일반 성공 코드만 주는 변형과 차이가 있습니다.')])}
def run():
    additions={}
    for path in (ROOT/'course/lesson-parts').glob('*.json'):
        for lesson in json.loads(path.read_text(encoding='utf-8')):
            key=lesson['id']
            if key not in ROWS:continue
            practice=dict(lesson.get('practice',{}));practice['expected']=ROWS[key][2]
            additions[key]=dict(concepts=[],reading_support=None,deep_dive=[],goal=ROWS[key][1],experiment={'title':'종이에 따라 해 보기','steps':[ROWS[key][2]]},practice=practice)
    return rewrite(ROWS,'tools/rewrite_os_beginner_364.py',additions)
if __name__=='__main__':print(json.dumps(run(),ensure_ascii=False))
